import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();
  group.userData.handlers = {};

  // Plane geometry (static backdrop for the card)
  const geometry = new ctx.THREE.PlaneGeometry(7, 6);
  const material = new MeshBasicNodeMaterial({
    color: 0x0b0b10,
    transparent: true,
    opacity: 0,
  });
  const mesh = new ctx.THREE.Mesh(geometry, material);
  group.add(mesh);

  // Load texture if provided
  let texture;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Text content
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new ctx.THREE.Group();
  for (const item of items) {
    const txt = typeof item === 'string' ? item : item.text;
    const opts = {
      fontSize: (item.typography && item.typography.fontSize) || 39,
      color: (config.intent?.visualSpec?.colors?.paper) || '#e8ecf2',
      align: 'center',
    };
    const txtObj = ctx.fontAtlas.createText(txt, opts);
    txtObj.position.set(0, 0, 0.01);
    textGroup.add(txtObj);
  }
  group.add(textGroup);

  // Entrance animation (rise‑in + fade‑in)
  const tl = gsap.timeline();
  tl.from(material, { opacity: 0, duration: 0.5, ease: 'power2.out' }, 0);
  tl.from(group.position, { y: -0.4, duration: 0.7, ease: 'power3.out' }, 0);

  // Cleanup
  group.userData.cleanup = () => {
    tl.kill();
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
    textGroup.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose();
        child.material?.dispose();
      }
    });
  };

  return group;
}
